create table ref_dw_cd_val(dw_cd_id string comment '仓库代码编号',dw_cd_chn_name string comment '仓库代码中文名称',dw_cd_val string comment '仓库代码取值',dw_cd_val_desc string comment '仓库代码取值描述',encd_mode string comment '编码方式',matn string comment '维护人',remark string comment '备注',src string comment '来源',busi_date string comment '业务日期',dw_cd_eng_name string comment '仓库代码英文名称') partitioned by (src_tbl string comment '源表') row format delimited fields terminated by ',' stored as orc;
